CREATE TABLE public.campus_chat (user_id uuid PRIMARY KEY,messages jsonb NOT NULL DEFAULT '[]'::jsonb,updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE ON public.campus_chat TO authenticated; GRANT ALL ON public.campus_chat TO service_role; ALTER TABLE public.campus_chat ENABLE ROW LEVEL SECURITY; CREATE POLICY "own assistant history" ON public.campus_chat FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.campus_ai_blocks (user_id uuid PRIMARY KEY,message text NOT NULL,status integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.campus_ai_blocks TO authenticated; GRANT ALL ON public.campus_ai_blocks TO service_role; ALTER TABLE public.campus_ai_blocks ENABLE ROW LEVEL SECURITY; CREATE POLICY "own AI access state" ON public.campus_ai_blocks FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.digital_ids (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL UNIQUE,token uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(),active boolean NOT NULL DEFAULT false,approved_by uuid,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE ON public.digital_ids TO authenticated; GRANT ALL ON public.digital_ids TO service_role; ALTER TABLE public.digital_ids ENABLE ROW LEVEL SECURITY; CREATE POLICY "own approved ID" ON public.digital_ids FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.campus_capability('admin') OR public.campus_capability('security')); CREATE POLICY "request own ID" ON public.digital_ids FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND NOT active AND approved_by IS NULL); CREATE POLICY "approve IDs" ON public.digital_ids FOR UPDATE TO authenticated USING(public.campus_capability('admin')) WITH CHECK(public.campus_capability('admin') AND approved_by=auth.uid());
CREATE TABLE public.campus_access (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),id_id uuid NOT NULL REFERENCES public.digital_ids(id),user_id uuid NOT NULL,direction text NOT NULL CHECK(direction IN ('Entry','Exit')),verified_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT ON public.campus_access TO authenticated; GRANT ALL ON public.campus_access TO service_role; ALTER TABLE public.campus_access ENABLE ROW LEVEL SECURITY; CREATE POLICY "own access history" ON public.campus_access FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.campus_capability('security') OR public.campus_capability('admin')); CREATE POLICY "security records access" ON public.campus_access FOR INSERT TO authenticated WITH CHECK((public.campus_capability('security') OR public.campus_capability('admin')) AND verified_by=auth.uid() AND EXISTS(SELECT 1 FROM public.digital_ids WHERE id=id_id AND user_id=campus_access.user_id AND active));
CREATE TABLE public.incident_responses (incident_id uuid PRIMARY KEY REFERENCES public.incident_reports(id),status text NOT NULL CHECK(status IN ('Acknowledged','Assigned','Responding','Resolved')),department text NOT NULL DEFAULT '',note text NOT NULL DEFAULT '',updated_by uuid NOT NULL DEFAULT auth.uid(),updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE ON public.incident_responses TO authenticated; GRANT ALL ON public.incident_responses TO service_role; ALTER TABLE public.incident_responses ENABLE ROW LEVEL SECURITY; CREATE POLICY "read incident response" ON public.incident_responses FOR SELECT TO authenticated USING(public.campus_capability('security') OR public.campus_capability('admin') OR EXISTS(SELECT 1 FROM public.incident_reports WHERE id=incident_id AND user_id=auth.uid())); CREATE POLICY "security manages response" ON public.incident_responses FOR ALL TO authenticated USING(public.campus_capability('security') OR public.campus_capability('admin')) WITH CHECK((public.campus_capability('security') OR public.campus_capability('admin')) AND updated_by=auth.uid()); CREATE POLICY "authorized incident monitoring" ON public.incident_reports FOR SELECT TO authenticated USING(public.campus_capability('security') OR public.campus_capability('admin'));